From 507213bf14a310dd0a6b2515f12c2e05595a64df Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:53:49 +0100
Subject: [PATCH] shell/panelview: Keep the result of forwarded drag events

Drag events in the panel's margins are re-sent at a position inside the
containment, but whether that copy was accepted got lost, so drags that
entered through the margin were refused there; copy the result back.

BUG: 511107
---
 shell/panelview.cpp | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..dabcc913f4 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -1261,6 +1261,8 @@ bool PanelView::event(QEvent *e)
             m_fakeEventPending = true;
             QCoreApplication::sendEvent(this, &de2);
             m_fakeEventPending = false;
+            de->setDropAction(de2.dropAction());
+            de->setAccepted(de2.isAccepted());
             return true;
         }
         break;
@@ -1280,6 +1282,8 @@ bool PanelView::event(QEvent *e)
             m_fakeEventPending = true;
             QCoreApplication::sendEvent(this, &de2);
             m_fakeEventPending = false;
+            de->setDropAction(de2.dropAction());
+            de->setAccepted(de2.isAccepted());
             return true;
         }
         break;
@@ -1293,6 +1297,8 @@ bool PanelView::event(QEvent *e)
             m_fakeEventPending = true;
             QCoreApplication::sendEvent(this, &de2);
             m_fakeEventPending = false;
+            de->setDropAction(de2.dropAction());
+            de->setAccepted(de2.isAccepted());
             return true;
         }
         break;
-- 
